const arrayData = {{workflowparams:arrayData}};
const allData = arrayData[0];
const unique = `${allData.create_user || ""}_${Date.now()}`;

return {
  unique
};

const arrayData = {{workflowparams:arrayData}}
const currentIndexRaw = {{node:get_cache_node_OMu4rhrM.data}}
const index = currentIndexRaw ? parseInt(currentIndexRaw, 10) : 0
const saveAs = {{workflowparams:saveAs}}
const pageStatus = {{workflowparams:pageStatus}}

let data = arrayData[index];
let invalidMessage = "";

// table_putaway_item is a tree: an item bundle is one row with its items under
// `children`. The bundle row holds no stock of its own, so the quantity that
// makes a putaway worth completing can sit on an item under it — walk both.
const flattenPutawayRows = (rows) => {
  const flat = [];

  for (const row of rows || []) {
    flat.push(row);

    const children = Array.isArray(row.children) ? row.children : [];

    for (const child of children) {
      flat.push(child);
    }
  }

  return flat;
};

// Validation: For saveAs "Completed", at least one item must have putaway_qty > 0
if (saveAs === "Completed") {
  const putawayRows = flattenPutawayRows(data.table_putaway_item);
  const hasPutawayQty = putawayRows.length > 0 &&
    putawayRows.some(item => item.putaway_qty > 0);

  if (!hasPutawayQty) {
    invalidMessage = "Cannot complete putaway. At least one item must have putaway quantity greater than 0.";
  }
}

if (saveAs !== "Cancelled") {
  if (saveAs === "Draft") {
    if (
      data.to_id_type !== -9999 &&
      (!data.to_id ||
        data.to_id === null ||
        data.to_id === "")
    ) {
      data.to_id = "draft";
    }
  } else {
    if (
      data.to_id_type !== -9999 &&
      (!data.to_id ||
        data.to_id === null ||
        data.to_id === "" ||
        data.to_status === "Draft")
    ) {
      data.to_id = "issued";
    }
  }
}

let updatedStatus = {{workflowparams:saveAs}}
if (saveAs === "Completed" && pageStatus === "Add") {
  updatedStatus = "Created"
}

// Interpolated into sql_node_LockGate, and arrayData is caller-supplied.
// Putaway ids are snowflake bigints, so digits-only is exact, not a guess;
// "0" matches no row, which fails closed as "under processing".
const lockId = /^[0-9]+$/.test(String(data.id || "")) ? String(data.id) : "0";

return {
  data,
  updatedStatus,
  nextIndex: index + 1,
  invalidMessage,
  lockId,
  isInvalid: invalidMessage === "" ? 0 : 1
}

const rows = {{node:sql_node_LockGate.data}} || [];
const list = Array.isArray(rows) ? rows : [rows];
const row = list[0];

// A crashed run can never release the mutex in-flow, so a lock this old is
// treated as abandoned and taken over.
const STALE_SEC = 900;

// 0 = free, take the lock   1 = held by a live run   2 = already Completed
let lockState = 1;
let staleRecovered = 0;

if (row && row.id) {
  if (row.to_status === "Completed") {
    lockState = 2;
  } else if (Number(row.is_processing) === 1) {
    const age = Number(row.lock_age_sec);
    // A negative or unparseable age means the clock assumption is off; stay
    // locked rather than risk stealing a lock from a run still in progress.
    if (isFinite(age) && age > STALE_SEC) {
      lockState = 0;
      staleRecovered = 1;
    }
  } else {
    lockState = 0;
  }
}

return {
  lockState,
  staleRecovered
}

return {
  required_fields: JSON.stringify([
      { name: "plant_id", label: "Plant" },
      { name: "to_id", label: "Transfer Order No" },
      { name: "ref_doc_type", label: "Reference Document Type" },
      {
        name: "table_putaway_item",
        label: "Putaway Items",
        isArray: true,
        arrayType: "object",
        arrayFields: [],
      },
]),
  data: JSON.stringify({
    plant_id: {{node:code_node_kku8SAT9.data.data.plant_id}},
    to_id: {{node:code_node_kku8SAT9.data.data.to_id}},
    ref_doc_type: {{node:code_node_kku8SAT9.data.data.ref_doc_type}},
    table_putaway_item: {{node:code_node_kku8SAT9.data.data.table_putaway_item}},
  })
}

let data = {{node:code_node_kku8SAT9.data.data}}

// Helper function to format qty and price fields to 3 decimal places
const formatNumber = (value) => {
  if (value === null || value === undefined || value === "") return 0;
  return parseFloat(value).toFixed(3);
};

// table_putaway_item is a tree: an item bundle is one row with its items under
// `children`. The items are stock lines in their own right, so their quantities
// are formatted the same way — and rebuilt under the row they belong to, so the
// tree is what gets written to the document.
const formatPutawayLine = (item) => {
  const formatted = {
    ...item,
    received_qty: formatNumber(item.received_qty),
    qty_to_putaway: formatNumber(item.qty_to_putaway),
    putaway_qty: formatNumber(item.putaway_qty),
    pending_process_qty: formatNumber(item.pending_process_qty),
  };

  if (Array.isArray(item.children)) {
    formatted.children = item.children.map((child) => formatPutawayLine(child));
  }

  return formatted;
};

// Format qty fields in table_putaway_item
if (data.table_putaway_item && data.table_putaway_item.length > 0) {
  data.table_putaway_item = data.table_putaway_item.map(formatPutawayLine);
}

// Format qty fields in table_putaway_records if exists
if (data.table_putaway_records && data.table_putaway_records.length > 0) {
  data.table_putaway_records = data.table_putaway_records.map(item => ({
    ...item,
    store_in_qty: formatNumber(item.store_in_qty),
  }));
}

return {
  data
}

const pageStatus = {{workflowparams:pageStatus}}

let putawayData = {{node:code_node_kku8SAT9.data.data}}

if (pageStatus === 'Add') {
  const rawData = {{node:add_node_sjzNkA59.data}}
  putawayData = rawData[0]
  putawayData.table_putaway_item = {{node:search_node_hrs91pu9.data.data}}
}

return {
  putawayData
}

const pageStatus = {{workflowparams:pageStatus}}

let putawayData = {{node:code_node_kku8SAT9.data.data}}

if (pageStatus === 'Add') {
  const rawData = {{node:add_node_sjzNkA59.data}}
  putawayData = rawData[0]
  putawayData.table_putaway_item = {{node:search_node_hrs91pu9.data.data}}
} else {
  putawayData = {{node:get_node_gbE86P3e.data.data}}
}

const grId = putawayData.gr_id

const filteredPutawayItems = putawayData.table_putaway_item.filter((item) => item.line_status !== "Cancelled",);

return {
  grId,
  filteredPutawayItems,
}
